```tsx
import { useEffect, useId, useState, type ReactElement } from "react";
import "./CodeCard.css";

export interface CodeCardProps {
  title: string;
  code: string;
  onCopy: () => void;
}

export function CodeCard({ title, code, onCopy }: CodeCardProps): ReactElement {
  const titleId = useId();
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    if (!copied) {
      return;
    }
    const timer = window.setTimeout(() => setCopied(false), 2000);
    return () => window.clearTimeout(timer);
  }, [copied]);

  const handleCopy = (): void => {
    onCopy();
    setCopied(true);
  };

  return (
    <section className="code-card" aria-labelledby={titleId}>
      <header className="code-card__header">
        <h2 className="code-card__title" id={titleId}>
          {title}
        </h2>
        <button type="button" className="code-card__copy" onClick={handleCopy}>
          Copy
        </button>
      </header>

      <pre className="code-card__code" tabIndex={0} aria-label={`${title}, SQL`}>
        <code>{code}</code>
      </pre>

      <p className="code-card__status" role="status">
        {copied ? "Copied to clipboard" : ""}
      </p>
    </section>
  );
}
```

